-- ---- 6. Vérifications (la migration échoue si le compte n'y est pas) --------
do $check$
declare
	v_cm1 integer; v_cm2 integer; v_6 integer; v_sans_noeud integer; v_noms integer;
	v_retires integer; v_refs integer; v_ordre integer;
begin
	select count(*) into v_cm1 from public.curriculum_points where grade = 'CM1';
	select count(*) into v_cm2 from public.curriculum_points where grade = 'CM2';
	select count(*) into v_6 from public.curriculum_points where grade = '6';
	select count(*) into v_sans_noeud from public.curriculum_points where grade in ('CM1', 'CM2', '6') and node_id is null;
	select count(*) into v_noms from public.curriculum_points where grade in ('CM1', 'CM2', '6') and ((code = 'CM1-001' and name = $pt$Dénombrer des collections en les organisant$pt$) or (code = 'CM1-034' and name = $pt$Comparer, ordonner, par ordre croissant ou décroissant, des nombres décimaux donnés par leur écriture à virgule en utilisant les symboles =, < et >$pt$) or (code = 'CM1-039' and name = $pt$Ajouter un nombre entier inférieur à 10, d'unités, de dizaines, de centaines, de dixièmes ou de centièmes à un nombre décimal, lorsqu'il n'y a pas de retenue$pt$) or (code = 'CM1-054' and name = $pt$Résoudre des problèmes additifs en une étape du type « parties-tout »$pt$) or (code = 'CM1-087' and name = $pt$Déterminer des aires en utilisant une unité et un quadrillage$pt$) or (code = 'CM1-120' and name = $pt$Recueillir des données et produire un tableau pour les présenter$pt$) or (code = 'CM1-121' and name = $pt$Lire et interpréter les données d'un tableau à simple entrée$pt$) or (code = 'CM2-034' and name = $pt$Comparer, ordonner par ordre croissant ou décroissant des nombres décimaux donnés par leur écriture à virgule en utilisant les symboles =, < et >$pt$) or (code = 'CM2-040' and name = $pt$Ajouter un nombre entier à un nombre décimal lorsqu'il n'y a pas de retenue$pt$) or (code = 'CM2-058' and name = $pt$Résoudre des problèmes additifs en une étape$pt$) or (code = 'CM2-072' and name = $pt$Déterminer des aires en utilisant une unité et un quadrillage$pt$) or (code = 'CM2-075' and name = $pt$Déterminer l'aire d'un carré$pt$) or (code = 'CM2-106' and name = $pt$Recueillir des données et produire un tableau pour présenter des données recueillies$pt$) or (code = 'CM2-107' and name = $pt$Lire et interpréter les données d'un tableau$pt$) or (code = '6-103' and name = $pt$Connaître des grands nombres entiers, jusqu'au milliard$pt$) or (code = '6-114' and name = $pt$Additionner des nombres décimaux$pt$) or (code = '6-116' and name = $pt$Connaître le lien entre la multiplication par 0,1, par 0,01 et par 0,001 et la division par 10, 100 et par 1 000$pt$) or (code = '6-117' and name = $pt$Comprendre le sens de la multiplication de deux nombres décimaux en prenant appui sur le calcul de l'aire d'un rectangle et sur des conversions d'unités$pt$) or (code = '6-142' and name = $pt$Utiliser des modèles pré-algébriques (schémas en barre) pour résoudre des problèmes algébriques$pt$) or (code = '6-144' and name = $pt$Calculer le périmètre d'un carré$pt$) or (code = '6-151' and name = $pt$Connaître la formule de l'aire d'un carré$pt$) or (code = '6-152' and name = $pt$Calculer l'aire d'un carré$pt$) or (code = '6-155' and name = $pt$Déterminer un volume en lien avec le dénombrement d'assemblages de cubes$pt$) or (code = '6-176' and name = $pt$Utiliser la valeur de la somme des mesures des angles d'un triangle pour calculer des angles, effectuer des constructions et résoudre des problèmes$pt$) or (code = '6-181' and name = $pt$Voir dans l'espace des assemblages de cubes : passage, dans les deux sens, entre l'objet à trois dimensions et ses diverses représentations à deux dimensions ; dénombrements$pt$));
	select count(*) into v_retires from public.curriculum_points where code in ('CM1-096', 'CM2-086');
	select count(*) into v_refs from public.curriculum_point_automatismes a join public.curriculum_points p on p.id = a.point_id where (p.code = 'CM2-123' and a.grade = '6') or (p.code = 'CM2-124' and a.grade = '6') or (p.code = 'CM2-125' and a.grade = '6') or (p.code = '6-201' and a.grade = '4') or (p.code = '6-198' and a.grade = '5') or (p.code = '6-199' and a.grade = '2') or (p.code = '6-201' and a.grade = '2') or (p.code = '6-199' and a.grade = '1_SPE') or (p.code = '6-201' and a.grade = '1_SPE') or (p.code = '6-199' and a.grade = '1_GEN') or (p.code = '6-201' and a.grade = '1_GEN') or (p.code = '6-199' and a.grade = '1_TECHNO') or (p.code = '6-201' and a.grade = '1_TECHNO') or (p.code = '6-199' and a.grade = 'T_COMP') or (p.code = '6-201' and a.grade = 'T_COMP') or (p.code = '6-199' and a.grade = 'T_SPE') or (p.code = '6-201' and a.grade = 'T_SPE');
	select count(*) into v_ordre from (
		select grade, count(distinct display_order) = count(*) and min(display_order) = 1 and max(display_order) = count(*) as ok
		  from public.curriculum_points where grade in ('CM1', 'CM2', '6') group by grade) s where ok;
	if v_cm1 <> 138 or v_cm2 <> 124 or v_6 <> 101 or v_sans_noeud <> 0 or v_noms <> 25
	   or v_retires <> 0 or v_refs <> 17 or v_ordre <> 3 then
		raise exception 'passe cycle 3 incohérente : CM1=%, CM2=%, 6e=%, sans nœud=%, libellés=%, retirés restants=%, réfs ajoutées=%, ordres valides=%',
			v_cm1, v_cm2, v_6, v_sans_noeud, v_noms, v_retires, v_refs, v_ordre;
	end if;
end $check$;
